      const ok = await ctx.confirm({ title: 'Promote to ' + stageLabel(to), body: to === 'test' ? '<p>The development app is packaged now as v' + version + ' and deployed onto <b>' + esc(pipeline.stages.test.app) + '</b>. The test app is backed up first.</p>' : '<p>The package that passed test, <b>v' + version + '</b> (' + esc((d.packages.find((p) => p.version === version) || {}).hash || '') + '), is deployed onto <b>' + esc(pipeline.stages.production.app) + '</b> once ' + esc(pipeline.approvalWorkflow) + ' approves it. The production app is backed up first.</p>', ok: 'Promote' });
