          if (type === 'enum' || (type === 'lookup' && val('source') === 'static')) { nf.options = String(val('options') || '').split('\n').map((s) => s.trim()).filter(Boolean); if (!nf.options.length) { ctx.toast('400: options are needed.', 'danger'); return; } }
          if (type === 'reference') nf.entity = val('entity');
