    const note = st.apiNote === 'key' ? UI.notice('<b>A key limited to this app and one entity.</b> Made on Settings, API keys, with records:read: it lists that entity\'s rows (masked as its policies say) and gets <span class="mono">403 step scope</span> on a write, on another entity or app, and on anything outside <span class="mono">/api/apps</span>. The audit event apikey.created carries the app and entity.', 'info', UI.btn('Dismiss', { size: 'xs', kind: 'ghost', attrs: 'data-apinote' }))
      : st.apiNote === 'schema' ? UI.notice('<b>Version ' + sc.version + ' just landed through the schema API.</b> The field is in the app now; <span class="mono">openapi.json</span> and the client answer with the new version and <span class="mono">ETag "' + esc(sc.hash.slice(0, 12)) + '…"</span>; a client built on the old hash still works for the fields it knows.', 'ok', UI.btn('Dismiss', { size: 'xs', kind: 'ghost', attrs: 'data-apinote' })) : '';
